show_nights.script:
storage.showNights = (storage.showNights || 0) + 1
const n = storage.showNights
if (n === 3) {
  effects.push({ type: 'story', instruction: "Word's got round: farmers are walking in from three towns over just to see the new act." })
  effects.push({ type: 'npc-relationship', npc: 'Dreamer', operator: 'add', value: 10 })
} else if (n === 10) {
  effects.push({ type: 'story', instruction: "Ten shows in and the new act's name is painted on the side of a wagon, right under Bramble's." })
} else {
  skip = true
}
